import{_ as t,o,c as n,ae as a}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"","description":"Deploy a Fresh application to Deno Deploy in seconds, making it available on\\nthe edge globally - resulting in fantastic user latency worldwide.\\n","frontmatter":{"description":"Deploy a Fresh application to Deno Deploy in seconds, making it available on\\nthe edge globally - resulting in fantastic user latency worldwide.\\n"},"headers":[],"relativePath":"en/latest/1.x/getting-started/deploy-to-production.md","filePath":"en/latest/1.x/getting-started/deploy-to-production.md"}'),r={name:"en/latest/1.x/getting-started/deploy-to-production.md"};function i(l,e,s,d,p,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<p>As a final step in the getting started guide, we&#39;ll deploy the demo site to the public internet using <a href="https://deno.com/deploy" target="_blank" rel="noreferrer">Deno Deploy</a>. Deno Deploy is a globally distributed edge runtime built by the Deno company that allows developers to quickly and painlessly deploy web applications to the internet. Deno Deploy has edge nodes all over the world that serve traffic. Because of this, users worldwide have fantastic latency because their traffic is served from a server that is physically close to them.</p><p>To deploy to Deno Deploy, we&#39;ll make use of the GitHub integration. To use this the code needs to be pushed to a repository on GitHub. Once this has been done, one must go to the <a href="https://dash.deno.com/projects" target="_blank" rel="noreferrer">Deno Deploy dashboard</a> and create a new project.</p><p>Click on the &quot;New Project&quot; button and select the GitHub repository that contains the Fresh project. Select the &quot;Fresh&quot; framework preset, and click on &quot;Advanced options&quot;. Enter <code>deno task build</code> in the &quot;Build command&quot; field. Press &quot;Create project&quot;.</p><p>The project will now deploy to Deno Deploy. After this is done, the project will be available at https://$PROJECT_NAME.deno.dev.</p><p>Every time the code in the GitHub repository is updated, it will be deployed either as a preview or production deployment. Production deployments are only created for changes to the default/production branch (often <code>main</code>).</p>',5)])])}const y=t(r,[["render",i]]);export{u as __pageData,y as default};
